996	    //   name "sample_content.txt" is 18 bytes and the central directory agrees on 18.
997	    //   This inconsistency drives the rewrite past the original buffer length on close().
998	    static const unsigned char craftedZip[] = {
999	        0x50, 0x4b, 0x03, 0x04, 0x0a, 0x00, 0x00, 0x00, 0x00, 0x00, 0x36, 0x42,
1000	        0x9c, 0x5a, 0xfa, 0x29, 0x42, 0xbc, 0x18, 0x00, 0x00, 0x00, 0x18, 0x00,
1001	        0x00, 0x00, 0x12, 0x10, 0x1c, 0x00, 0x73, 0x61, 0x6d, 0x70, 0x6c, 0x65,
1002	        0x5f, 0x63, 0x6f, 0x6e, 0x74, 0x65, 0x6e, 0x74, 0x2e, 0x74, 0x78, 0x74,
1003	        0x55, 0x54, 0x09, 0x00, 0x03, 0xa8, 0x39, 0x0f, 0x68, 0xa8, 0x39, 0x0f,
1004	        0x68, 0x75, 0x78, 0x0b, 0x00, 0x01, 0x04, 0x00, 0x00, 0x00, 0x00, 0x04,
1005	        0x00, 0x00, 0x00, 0x00, 0x41, 0x46, 0x4c, 0x2b, 0x2b, 0x20, 0x66, 0x75,
1006	        0x7a, 0x7a, 0x20, 0x74, 0x65, 0x73, 0x74, 0x20, 0x73, 0x61, 0x6d, 0x70,
1007	        0x6c, 0x65, 0x2e, 0x0a, 0x50, 0x4b, 0x01, 0x02, 0x1e, 0x03, 0x0a, 0x00,
1008	        0x00, 0x00, 0x00, 0x00, 0x36, 0x42, 0x9c, 0x5a, 0xfa, 0x29, 0x42, 0xbc,
1009	        0x18, 0x00, 0x00, 0x00, 0x18, 0x00, 0x00, 0x00, 0x12, 0x00, 0x18, 0x00,
1010	        0x00, 0x00, 0x00, 0x00, 0x01, 0x00, 0x00, 0x00, 0xa4, 0x81, 0x00, 0x00,
1011	        0x00, 0x00, 0x73, 0x61, 0x6d, 0x70, 0x6c, 0x65, 0x5f, 0x63, 0x6f, 0x6e,
1012	        0x74, 0x65, 0x6e, 0x74, 0x2e, 0x74, 0x78, 0x74, 0x55, 0x54, 0x05, 0x00,
1013	        0x03, 0xa8, 0x39, 0x0f, 0x68, 0x75, 0x78, 0x0b, 0x00, 0x01, 0x04, 0x00,
