    ifs.read(buffer, bufferSize);
    ifs.close();

    z1.unlink();

    ZipArchive* z2 = ZipArchive::fromBuffer(buffer, bufferSize);
    assert(!z2->isMutable());

    assert(z2->getNbEntries() == 2);
