// 1. retained object + copies across longer/shorter/empty replacements, both states, all read kinds
void scenario_replace() {
    buildOriginal("v_replace.zip");
    ZipArchive z("v_replace.zip");
    z.open(ZipArchive::Write);
    ZipEntry e = z.getEntry("old.txt");
    CHECK(!e.isNull());
    CHECK(e.getSize()==11);
    ZipEntry copy = e; // object copy

    struct { const string* data; } steps[3] = { {&LONGER}, {&SHORTER}, {&(string const&)string()} };
    const string empty;
    steps[2].data = &empty;

    for (int i=0;i<3;i++) {
        const string& d = *steps[i].data;
        z.addData("old.txt", d.data(), d.size());

        // pointer (binary), text, binary string on retained object and on the copy
        unsigned char* pb = e.readAsBinary(ZipArchive::Current);
        CHECK(pb!=nullptr);
        CHECK(memcmp(pb, d.data(), d.size())==0);
        delete[] pb;
        unsigned char* pbc = copy.readAsBinary(ZipArchive::Current);
        CHECK(pbc!=nullptr && memcmp(pbc,d.data(),d.size())==0);
        delete[] pbc;

        string t = e.readAsText(ZipArchive::Current);
        CHECK(t==d);
        basic_string<libzippp_uint8> bs = e.readAsBinaryString(ZipArchive::Current);
        CHECK(bs.size()==d.size());
        CHECK(memcmp(bs.data(), d.data(), d.size())==0);

        // Original always returns the open-time content
        string to = e.readAsText(ZipArchive::Original);
        CHECK(to==ORIG);
        basic_string<libzippp_uint8> bso = e.readAsBinaryString(ZipArchive::Original);
        CHECK(bso==ORIG);

        // chunked current/original with several chunk sizes (incl. 0=default and non-divisor)
        libzippp_uint64 cszs[4] = { 0, 2, 1, 100 };
        for (libzippp_uint64 csz : cszs) {
            ostringstream out;
            int r = e.readContent(out, ZipArchive::Current, csz);
            CHECK(r==LIBZIPPP_OK);
            CHECK(out.str()==d);
            ostringstream outo;
            CHECK(e.readContent(outo, ZipArchive::Original, csz)==LIBZIPPP_OK);
            CHECK(outo.str()==ORIG);
        }

        // callback chunked: ensure complete and non-repeating
        string acc;
        int r = z.readEntry(e, [&](const void* p, libzippp_uint64 n){ acc.append((const char*)p,n); return true; },
                            ZipArchive::Current, 3);
        CHECK(r==LIBZIPPP_OK && acc==d);
    }
    z.close();
}

// length parameter semantics: 0 whole, N prefix, >len all; zero bytes preserved; NUL not counted
void scenario_length_and_zeros() {
    string bin;
    bin.push_back('A'); bin.push_back('\0'); bin.push_back('B'); bin.push_back('\0'); bin.push_back('C');
    ZipArchive z("v_len.zip");
    z.open(ZipArchive::New);
    z.addData("b", bin.data(), bin.size());
    z.close();

    ZipArchive r("v_len.zip");
    r.open(ZipArchive::ReadOnly);
    ZipEntry e = r.getEntry("b");

    string all = e.readAsText(ZipArchive::Current, 0);
    CHECK(all==bin && all.size()==5);
    string pre = e.readAsText(ZipArchive::Current, 2);
    CHECK(pre.size()==2 && pre[0]=='A' && pre[1]=='\0');
    string big = e.readAsText(ZipArchive::Current, 999);
    CHECK(big==bin);

    // text pointer allocates content+1 and appends NUL not counted in content length
    char* p = (char*)r.readEntry(e, true, ZipArchive::Current, 0);
    CHECK(p!=nullptr && p[5]=='\0' && memcmp(p,bin.data(),5)==0);
    delete[] p;
    // binary pointer has no extra byte
    char* pb = (char*)r.readEntry(e, false, ZipArchive::Current, 0);
    CHECK(pb!=nullptr && pb[0]=='A' && pb[1]=='\0');
    delete[] pb;

    // prefix keeps embedded zero
    basic_string<libzippp_uint8> bpre = e.readAsBinaryString(ZipArchive::Current, 3);
    CHECK(bpre.size()==3 && bpre[0]=='A' && bpre[1]==0 && bpre[2]=='B');

    // chunked prefix not applicable (chunk reads whole); verify whole via stream
    ostringstream out;
    CHECK(e.readContent(out)==LIBZIPPP_OK && out.str()==bin);
    r.close();
}

