    char* po = (char*)z.readEntry("other.txt",false,ZipArchive::Original);
    CHECK(po!=nullptr && memcmp(po,"OTHER",5)==0); delete[] po;
    char* pc = (char*)z.readEntry("other.txt",false,ZipArchive::Current);
