// callback false / stream failure stop with existing conventions; empty file chunked succeeds
void scenario_output_failures() {
    buildOriginal("v_fail.zip");
    ZipArchive z("v_fail.zip");
    z.open(ZipArchive::Write);
    z.addData("old.txt", LONGER.data(), LONGER.size());
    ZipEntry e = z.getEntry("old.txt",false,true,ZipArchive::Original); // size 11 captured
    // callback that stops immediately
    int delivered=0;
    int r = z.readEntry(e, [&](const void*,libzippp_uint64){++delivered;return false;}, ZipArchive::Current, 4);
    CHECK(r==LIBZIPPP_ERROR_OWRITE_FAILURE);

    // failing stream
    ostringstream out;
    out.setstate(ios::badbit);
    CHECK(z.readEntry(e, out, ZipArchive::Current, 4)==LIBZIPPP_ERROR_INVALID_PARAMETER); // !ofOutput checked first

    // empty file chunked: success, no bytes, chunk size 0 default
    z.addData("old.txt", "", 0);
    ostringstream eo;
    CHECK(e.readContent(eo, ZipArchive::Current, 0)==LIBZIPPP_OK);
    CHECK(eo.str().empty());
    int cc=0;
    CHECK(z.readEntry(e,[&](const void*,libzippp_uint64){++cc;return true;},ZipArchive::Current,0)==LIBZIPPP_OK);
    CHECK(cc==0);
    // original empty-less entry still original content
    CHECK(e.readAsText(ZipArchive::Original)==ORIG);
    z.close();
}

// reads do not commit/undo pending changes; read-only behavior unchanged; reopened file has changes
void scenario_persistence_and_readonly() {
    buildOriginal("v_persist.zip");
    ZipArchive z("v_persist.zip");
    z.open(ZipArchive::Write);
    z.addData("old.txt", SHORTER.data(), SHORTER.size());
    CHECK(z.getEntry("old.txt").readAsText(ZipArchive::Current)==SHORTER);
    // reading must not have committed anything: file on disk still original
    {
        ZipArchive ro("v_persist.zip");
        ro.open(ZipArchive::ReadOnly);
        CHECK(ro.getEntry("old.txt").getSize()==11);
        CHECK(ro.getEntry("old.txt").readAsText()==ORIG);
        ro.close();
    }
    CHECK(z.close()==LIBZIPPP_OK);
    {
        ZipArchive ro("v_persist.zip");
        ro.open(ZipArchive::ReadOnly);
        CHECK(ro.getEntry("old.txt").readAsText()==SHORTER);
        // default state Current on read-only behaves as before
        void* p = ro.readEntry("old.txt", true);
        CHECK(p!=nullptr); delete[] p;
        ro.close();
    }
}

